import {
	Component,
	Element,
	Host,
	Method,
	Prop,
	State,
	h,
} from "@stencil/core";
import { generateShortID } from "../../utils/function-helper";

import {
	createFloatingContainer,
	getFloatElmZIndex,
	hideFloatingContainer,
	showFloatingContainer,
} from "../../utils/floating-container";

/**
 * @since 0.0.6
 * @status stable
 *
 */
@Component({
	tag: "hbr-tab-popover",
	styleUrl: "tab-popover.scss",
	shadow: true,
})
export class TabPopover {
	tabElement: HTMLElement;
	panel: HTMLElement;
	_floatingListener = null;

	@Element() host: HTMLHbrTabPopoverElement;

	// if used in navigation
	@Prop({ reflect: true }) nav = false;

	// if used in toggleable nav
	@Prop({ reflect: true }) collapsed = false;

	/** User assigned or self generated popover Id for reference */
	@Prop({ reflect: true })
	contentId?: string = `hbr-tab-popover-id-${generateShortID()}`;

	/** z-index value for popover, uncontrolled. */
	@Prop({ mutable: true }) zIndex?: number = 1;

	/** The distance in pixels from which to offset the popover away from its target. */
	@Prop() distance = 0;

	/**
	 * The preferred placement of the popover. Note that the actual placement may vary as needed to keep the popover
	 * inside of the viewport.
	 */
	@Prop({ reflect: true }) placement?:
		| "auto"
		| "top"
		| "top-start"
		| "top-end"
		| "right"
		| "right-start"
		| "right-end"
		| "bottom"
		| "bottom-start"
		| "bottom-end"
		| "left-start"
		| "left-end"
		| "left" = "right";

	// if opened popover or not
	@State() active = false;

	// if opened popover or not
	@State() focusEvent = false;

	/** Sets focus to the tab-popover. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.onHover(options);
	}

	/** Removes focus to the tab-popover. */
	@Method()
	async removeFocus(event) {
		this.onLeave(event);
	}

	handleKeyDown = (event) => {
		if (["ArrowRight", "Enter"].includes(event.key)) {
			event.stopPropagation();
			const popoverDiv = this.host.ownerDocument.querySelector(
				`#${this.contentId}`,
			) as HTMLElement;
			if (popoverDiv) {
				const menuItems = popoverDiv.querySelectorAll("hbr-menu-item");
				const selectedItem =
					menuItems && Array.from(menuItems).filter((item) => item.checked);
				if (selectedItem?.[0]) {
					selectedItem[0].focus();
				} else {
					const menuItemElem = popoverDiv.querySelector("hbr-menu-item");
					menuItemElem?.focus();
				}
			}
		}
	};

	onHover = async (options) => {
		if (this.focusEvent === null) {
			this.focusEvent = options.type === "focusin";
		}

		if (!this.active) {
			const popoverDiv = this.host.ownerDocument.querySelector(
				`#${this.contentId}`,
			) as HTMLElement;
			this._floatingListener = await showFloatingContainer(
				this.host,
				popoverDiv,
				{
					distance: this.distance,
					placement: this.collapsed ? "bottom-end" : "right-start",
					marginTop: this.collapsed ? -40 : 0,
					zIndex: this.zIndex,
					delay: 0,
					marginLeft: this.collapsed ? 50 : 0,
				},
			);
			this.active = true;
		}
		const tab = this.host.shadowRoot.querySelector(
			"hbr-tab",
		) as HTMLHbrTabElement;
		tab.setFocus(options);
	};

	handlePanelKeyDown = (event) => {
		if (["ArrowLeft", "Escape"].includes(event.key)) {
			const activeEl = document.activeElement as HTMLElement;
			const id = activeEl.closest(".hbr-tab-popover").id;
			const popover = document.querySelector(
				`[content-id=${id}]`,
			) as HTMLElement;
			const tab = popover.shadowRoot.querySelector(
				"hbr-tab",
			) as HTMLHbrTabElement;
			tab.setFocus({ preventScroll: true });
		}
	};

	onLeave = (event) => {
		this.focusEvent = null;
		// find the next element from moving out
		let nextTarget = event && (event.toElement || event.relatedTarget);
		let isCorspondingFloatingElem = false;
		while (!isCorspondingFloatingElem && nextTarget) {
			if (nextTarget.id === this.contentId) {
				isCorspondingFloatingElem = true;
				break;
			}
			nextTarget = nextTarget.parentNode;
		}

		if (!isCorspondingFloatingElem && this.active) {
			const target = this.host.ownerDocument.querySelector(
				`#${this.contentId}`,
			) as HTMLElement;
			hideFloatingContainer(target, { delay: 0 });
			this.active = false;
		}

		const tab = this.host.shadowRoot.querySelector(
			"hbr-tab",
		) as HTMLHbrTabElement;
		tab.removeFocus();
	};

	connectedCallback() {
		const floatingContainer = createFloatingContainer(
			this.host.ownerDocument.body,
		);

		const curContainer = this.host.ownerDocument.createElement("div");
		curContainer.className = "hbr-tab-popover hbr-floating-component";
		curContainer.id = this.contentId;
		curContainer.setAttribute("part", "panel");
		curContainer.setAttribute("placement", this.placement);
		curContainer.addEventListener("mouseleave", this.onLeave);
		floatingContainer.appendChild(curContainer);
	}

	componentDidLoad() {
		// get max z-index of the reference
		if (this.zIndex === undefined) {
			this.zIndex = getFloatElmZIndex(this.host);
		}
		const popoverDiv = this.host.ownerDocument.querySelector(
			`#${this.contentId}`,
		) as HTMLElement;
		if (popoverDiv && popoverDiv.innerHTML === "") {
			const slot = this.panel.querySelector("slot");
			if (slot) {
				// extract all the items
				const slotContent = [...slot.assignedElements({ flatten: true })];
				// remove the slot element, which is just an empty tag
				this.panel.innerHTML = "";
				// copy the panel
				popoverDiv.appendChild(this.panel);

				// push into panel again, panel is now in floating container
				slotContent.forEach((r) => {
					this.panel.appendChild(r);
				});
			} else {
				console.warn("no slot in dropdown is found");
			}
		}
	}

	disconnectedCallback() {
		const popoverDiv = this.host.ownerDocument.querySelector(
			`#${this.contentId}`,
		) as HTMLElement;
		popoverDiv.removeEventListener("mouseleave", this.onLeave);
		if (popoverDiv) {
			popoverDiv.remove();
		}
		if (this._floatingListener) {
			this._floatingListener();
		}
	}

	render() {
		return (
			<Host>
				<div
					part="base"
					onMouseOver={this.onHover}
					onMouseLeave={this.onLeave}
					onFocusin={this.onHover}
					onFocus={this.onHover}
					onBlur={this.onLeave}
					onKeyDown={this.handleKeyDown}
					ref={(el) => {
						this.tabElement = el;
					}}
					class={{
						tab_popover: true,
						"tab_popover-collapsed": this.collapsed,
						"tab_popover-active": this.active,
					}}
				>
					{this.collapsed && this.active ? <div class="tab_overlay" /> : null}

					<hbr-tab
						nav
						vertical
						popOver
						hover={this.active}
						focusEvent={this.focusEvent}
					>
						<div slot="prefix">
							<slot name="icon" />
						</div>
						<div slot="label">
							<slot name="label" />
						</div>
					</hbr-tab>
					<div
						part="panel"
						onKeyDown={this.handlePanelKeyDown}
						class={{
							"popover-panel": true,
							"popover-panel-collapsed": this.collapsed,
						}}
						ref={(el) => {
							this.panel = el;
						}}
						aria-hidden={this.active ? "false" : "true"}
						aria-labelledby={this.contentId}
					>
						<slot />
					</div>
				</div>
			</Host>
		);
	}
}
