import { loadFloatingUi } from "./floating-ui";

type FloatingOpt = {
	distance?: number;
	placement:
		| "auto"
		| "top"
		| "top-start"
		| "top-end"
		| "right"
		| "right-start"
		| "right-end"
		| "bottom"
		| "bottom-start"
		| "bottom-end"
		| "left-start"
		| "left-end"
		| "left";
	zIndex?: number;
	delay?: number;
	marginLeft?: number;
	marginTop?: number;
	minWidth?: number;
};

type FloatingContainerChangeCallback = () => void;
type FloatTransitionEvent = MouseEvent & {
	toElement?: EventTarget | null;
};

